<template>
  <div class="workflow-market-page space-y-5">
    <PageHeader title="工作流模板市场" description="把成熟自动化作为独立副本导入个人或当前空间" :breadcrumbs="breadcrumbs">
      <template #actions>
        <router-link class="workflow-outline-button" to="/app"><i class="fa fa-arrow-left"></i>控制面板</router-link>
        <router-link class="workflow-outline-button" to="/app/workflows"><i class="fa fa-sitemap"></i>我的工作流</router-link>
        <router-link class="workflow-primary-button" to="/developer/workflows/new"><i class="fa fa-plus"></i>创建工作流</router-link>
      </template>
    </PageHeader>

    <section class="workflow-market-hero">
      <div>
        <p class="workflow-eyebrow">WORKFLOW GALLERY</p>
        <h2>从可复用的自动化模板开始</h2>
        <p>导入操作会创建一份属于当前用户或空间的独立工作流副本。修改副本不会改变市场模板，也不会影响其他使用者。</p>
        <form class="workflow-search" @submit.prevent="submitSearch"><i class="fa fa-search"></i><input v-model.trim="query" autocomplete="off" placeholder="搜索工作流名称、说明或标签" @focus="suggestionsOpen = true" @input="scheduleSearch" /><button v-if="query" type="button" aria-label="清除搜索" @click="clearSearch"><i class="fa fa-times"></i></button><button type="submit">搜索</button></form>
        <div v-if="suggestionsOpen && query && searchSuggestions.length" class="workflow-search-suggestions" role="listbox" aria-label="工作流搜索建议"><button v-for="item in searchSuggestions" :key="item.workflowId" type="button" role="option" @mousedown.prevent="selectSuggestion(item)"><span class="workflow-ranking__icon"><i class="fa fa-random"></i></span><span><b>{{ item.name }}</b><small>{{ item.categoryCode || '未分类' }} · {{ item.installCount }} 次导入</small></span><i class="fa fa-angle-right"></i></button></div>
        <div class="workflow-hot-tags"><span>推荐分类</span><button v-for="tag in hotTags" :key="tag" type="button" @click="setCategory(tag)">{{ tag }}</button></div>
      </div>
      <aside class="workflow-market-hero__aside"><div><i class="fa fa-copy"></i><b>{{ importedIds.size }}</b><span>本浏览器已导入</span></div><div><i class="fa fa-check-circle"></i><b>独立副本</b><span>导入后可安全编辑</span></div><div><i class="fa fa-bolt"></i><b>自动化</b><span>可在空间内运行</span></div></aside>
    </section>

    <section class="workflow-toolbar" aria-label="工作流模板筛选"><div class="workflow-tabs" role="tablist"><button v-for="filter in categoryTabs" :key="filter.value" type="button" role="tab" :aria-selected="category === filter.value" :class="{ active: category === filter.value }" @click="setCategory(filter.value)"><i :class="filter.icon"></i>{{ filter.label }}<small>{{ countByCategory(filter.value) }}</small></button></div><label>排序<select v-model="sortBy" @change="syncRoute"><option value="relevance">最相关</option><option value="published">最近发布</option><option value="imports">使用最多</option><option value="rating">评分最高</option></select></label></section>

    <section v-if="loading" class="workflow-grid workflow-grid--skeleton"><article v-for="index in 6" :key="index" class="workflow-card workflow-card--skeleton"><span></span><span></span><span></span><span></span></article></section>
    <section v-else-if="error" class="workflow-state workflow-state--error"><i class="fa fa-exclamation-triangle"></i><h2>工作流市场暂时无法加载</h2><p>{{ error }}</p><button type="button" @click="load">重新加载</button></section>

    <template v-else>
      <section v-if="!query && !category" class="workflow-section"><div class="workflow-section__heading"><div><p class="workflow-eyebrow">POPULAR TEMPLATES</p><h2>最受欢迎的工作流</h2><p>按市场返回的导入次数排列。</p></div><button type="button" @click="sortBy = 'imports'; syncRoute()">查看完整排行榜<i class="fa fa-arrow-right"></i></button></div><div class="workflow-ranking"><button v-for="(item, index) in rankings" :key="item.workflowId" type="button" @click="openDetail(item)"><b :class="rankClass(index)">{{ index + 1 }}</b><span class="workflow-ranking__icon"><i class="fa fa-random"></i></span><span><strong>{{ item.name }}</strong><small>{{ item.installCount }} 次导入 · {{ item.categoryCode || '未分类' }}</small></span><i class="fa fa-angle-right"></i></button><div v-if="!rankings.length" class="workflow-inline-empty">暂无工作流模板</div></div></section>

      <section class="workflow-content-grid"><aside class="workflow-categories"><div><h2>模板分类</h2><button v-if="category" type="button" @click="setCategory('')">清除</button></div><button type="button" :class="{ active: !category }" @click="setCategory('')"><i class="fa fa-th-large"></i>全部模板<span>{{ items.length }}</span></button><button v-for="item in categories" :key="item.name" type="button" :class="{ active: category === item.name }" @click="setCategory(item.name)"><i :class="categoryIcon(item.name)"></i>{{ item.name }}<span>{{ item.count }}</span></button><p><i class="fa fa-info-circle"></i>分类和标签来自模板市场；导入后仍需在 IDE 中校验并配置实际运行权限。</p></aside><section class="workflow-results"><div class="workflow-section__heading workflow-section__heading--compact"><div><p class="workflow-eyebrow">{{ query ? 'SEARCH RESULTS' : 'ALL TEMPLATES' }}</p><h2>{{ query ? `“${query}” 的结果` : '浏览模板' }}</h2></div><span>{{ filteredItems.length }} 个结果</span></div><div v-if="pagedItems.length" class="workflow-grid"><article v-for="item in pagedItems" :key="item.workflowId" class="workflow-card"><div class="workflow-card__header"><span class="workflow-icon"><i class="fa fa-random"></i></span><div><button type="button" class="workflow-name" @click="openDetail(item)">{{ item.name }}</button><p class="workflow-slug">{{ item.slug }}</p></div><span v-if="importedIds.has(item.workflowId)" class="workflow-imported"><i class="fa fa-check"></i>已导入</span></div><button type="button" class="workflow-description" @click="openDetail(item)">{{ item.description || '模板作者暂未填写使用说明。' }}</button><div class="workflow-tags"><span v-for="tag in itemTags(item).slice(0, 4)" :key="tag"><i class="fa fa-tag"></i>{{ tag }}</span><span v-if="!itemTags(item).length"><i class="fa fa-tag"></i>{{ item.categoryCode || '未分类' }}</span></div><div class="workflow-card__meta"><span><i class="fa fa-star"></i>{{ formatRating(item.ratingAverage) }}<small>({{ item.ratingCount }})</small></span><span><i class="fa fa-copy"></i>{{ item.installCount }} 次导入</span><time :title="item.publishedAt"><i class="fa fa-clock-o"></i>{{ formatDate(item.publishedAt) }}</time></div><div class="workflow-card__actions"><button type="button" class="workflow-detail-button" @click="openDetail(item)">查看详情</button><button type="button" class="workflow-import-button" :disabled="importingId === item.workflowId" @click="importTemplate(item)"><i :class="importingId === item.workflowId ? 'fa fa-spinner fa-spin' : importedIds.has(item.workflowId) ? 'fa fa-pencil' : 'fa fa-download'"></i>{{ importingId === item.workflowId ? '正在导入' : importedIds.has(item.workflowId) ? '再次导入' : '导入模板' }}</button></div></article></div><div v-else class="workflow-state"><i class="fa fa-search"></i><h2>未找到匹配模板</h2><p>请尝试调整关键词、分类或排序条件。</p><button v-if="query || category" type="button" @click="resetFilters">清除筛选</button></div><nav v-if="totalPages > 1" class="workflow-pagination"><button type="button" :disabled="page === 1" @click="goPage(page - 1)">上一页</button><span>第 {{ page }} / {{ totalPages }} 页</span><button type="button" :disabled="page === totalPages" @click="goPage(page + 1)">下一页</button></nav></section><aside class="workflow-sidebar" aria-label="工作流模板推荐"><section><header><h2>热门工作流</h2><span>Top {{ sidebarRankings.length }}</span></header><button v-for="(item,index) in sidebarRankings" :key="item.workflowId" type="button" @click="openDetail(item)"><b :class="rankClass(index)">{{ index + 1 }}</b><span class="workflow-ranking__icon"><i class="fa fa-random"></i></span><span><strong>{{ item.name }}</strong><small>{{ item.installCount }} 次导入 · {{ formatRating(item.ratingAverage) }} 分</small></span></button><p v-if="!sidebarRankings.length">暂无已发布模板</p></section><section><header><h2>最近发布</h2><i class="fa fa-clock-o"></i></header><button v-for="item in latestTemplates" :key="`latest-${item.workflowId}`" type="button" @click="openDetail(item)"><span class="workflow-ranking__icon"><i class="fa fa-random"></i></span><span><strong>{{ item.name }}</strong><small>{{ formatDate(item.publishedAt) }}</small></span></button><p v-if="!latestTemplates.length">暂无发布时间数据</p></section><section class="workflow-sidebar__note"><i class="fa fa-info-circle"></i><p>市场接口未提供作者字段，侧栏不会伪造活跃作者；排行只使用真实导入数、评分和发布时间。</p></section></aside></section>
    </template>

    <Teleport to="body"><div v-if="pendingImport" class="workflow-import-modal" @click.self="pendingImport = null"><section class="workflow-import-dialog" role="dialog" aria-modal="true" aria-labelledby="workflow-import-title"><header><div><p class="workflow-eyebrow">IMPORT TEMPLATE</p><h2 id="workflow-import-title">导入 {{ pendingImport.name }}</h2><p>为副本设置名称。名称和 slug 会在服务端进行最终校验。</p></div><button type="button" aria-label="关闭导入窗口" @click="pendingImport = null"><i class="fa fa-times"></i></button></header><form @submit.prevent="confirmImport"><label>工作流名称<input v-model.trim="importName" maxlength="120" required /></label><label>工作流标识<input v-model.trim="importSlug" pattern="[a-z0-9-]+" maxlength="120" required /><small>仅使用小写字母、数字和连字符。</small></label><div class="workflow-import-dialog__tip"><i class="fa fa-info-circle"></i>导入后的 DSL 和运行配置需要在工作流 IDE 中按当前空间权限检查。</div><footer><button type="button" class="workflow-detail-button" @click="pendingImport = null">取消</button><button type="submit" class="workflow-import-button" :disabled="Boolean(importingId)"><i v-if="importingId" class="fa fa-spinner fa-spin"></i>确认导入</button></footer></form></section></div></Teleport>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageHeader from '@/components/common/PageHeader.vue'
import { importWorkflowTemplateApi, listWorkflowMarketplaceApi, type WorkflowMarketplaceItem } from '@/api/modules/workflows'
import { useToastStore } from '@/stores/toastStore'

const route = useRoute(); const router = useRouter(); const toast = useToastStore()
const items = ref<WorkflowMarketplaceItem[]>([]); const loading = ref(false); const error = ref(''); const query = ref(''); const category = ref(''); const sortBy = ref<'relevance' | 'published' | 'imports' | 'rating'>('relevance'); const page = ref(1)
const importedIds = ref(new Set<string>()); const pendingImport = ref<WorkflowMarketplaceItem | null>(null); const importName = ref(''); const importSlug = ref(''); const importingId = ref(''); const suggestionsOpen = ref(false)
const pageSize = 9; let searchTimer: ReturnType<typeof setTimeout> | undefined
const breadcrumbs = [{ label: '控制面板', to: '/app' }, { label: '工作流市场' }]
const categoryTabs = [{ label: '全部', value: '', icon: 'fa fa-th-large' }, { label: '文件处理', value: 'file', icon: 'fa fa-folder-o' }, { label: '数据分析', value: 'data', icon: 'fa fa-bar-chart' }, { label: 'AI 自动化', value: 'ai', icon: 'fa fa-magic' }, { label: '通知提醒', value: 'notification', icon: 'fa fa-bell-o' }, { label: '定时任务', value: 'schedule', icon: 'fa fa-clock-o' }, { label: '审批流程', value: 'approval', icon: 'fa fa-check-square-o' }]
const categories = computed(() => Array.from(items.value.reduce((map, item) => { const value = item.categoryCode || '未分类'; map.set(value, (map.get(value) || 0) + 1); return map }, new Map<string, number>()).entries()).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count))
const hotTags = computed(() => categories.value.slice(0, 5).map(item => item.name))
const filteredItems = computed(() => { const term = query.value.toLocaleLowerCase(); return [...items.value].filter(item => { const categoryMatches = !category.value || `${item.categoryCode || ''} ${item.tagsJson || ''}`.toLocaleLowerCase().includes(category.value.toLocaleLowerCase()); return categoryMatches && (!term || `${item.name} ${item.description || ''} ${item.slug} ${item.categoryCode || ''} ${item.tagsJson || ''}`.toLocaleLowerCase().includes(term)) }).sort((a, b) => sortBy.value === 'imports' ? b.installCount - a.installCount : sortBy.value === 'rating' ? b.ratingAverage - a.ratingAverage : sortBy.value === 'published' ? dateValue(b.publishedAt) - dateValue(a.publishedAt) : Number(b.name.toLocaleLowerCase().startsWith(term)) - Number(a.name.toLocaleLowerCase().startsWith(term)) || dateValue(b.publishedAt) - dateValue(a.publishedAt)) })
const rankings = computed(() => [...items.value].sort((a, b) => b.installCount - a.installCount).slice(0, 5))
const sidebarRankings = computed(() => [...items.value].sort((a, b) => b.installCount - a.installCount || b.ratingAverage - a.ratingAverage).slice(0, 10))
const latestTemplates = computed(() => [...items.value].sort((a, b) => dateValue(b.publishedAt) - dateValue(a.publishedAt)).slice(0, 5))
const searchSuggestions = computed(() => { const term = query.value.toLocaleLowerCase(); return term ? items.value.filter(item => `${item.name} ${item.slug} ${item.description || ''} ${item.categoryCode || ''} ${item.tagsJson || ''}`.toLocaleLowerCase().includes(term)).slice(0, 6) : [] })
const totalPages = computed(() => Math.max(1, Math.ceil(filteredItems.value.length / pageSize))); const pagedItems = computed(() => filteredItems.value.slice((page.value - 1) * pageSize, page.value * pageSize))
function dateValue(value?: string) { const parsed = value ? new Date(value).getTime() : 0; return Number.isFinite(parsed) ? parsed : 0 }
function categoryIcon(value: string) { const lower = value.toLocaleLowerCase(); return lower.includes('file') ? 'fa fa-folder-o' : lower.includes('data') ? 'fa fa-bar-chart' : lower.includes('ai') ? 'fa fa-magic' : lower.includes('notice') || lower.includes('notification') ? 'fa fa-bell-o' : lower.includes('schedule') ? 'fa fa-clock-o' : lower.includes('approval') ? 'fa fa-check-square-o' : 'fa fa-random' }
function countByCategory(value: string) { return value ? items.value.filter(item => `${item.categoryCode || ''} ${item.tagsJson || ''}`.toLocaleLowerCase().includes(value.toLocaleLowerCase())).length : items.value.length }
function itemTags(item: WorkflowMarketplaceItem) { try { const parsed = JSON.parse(item.tagsJson || '[]'); return Array.isArray(parsed) ? parsed.map(String) : [] } catch { return [] } }
function formatRating(value: number) { return Number.isFinite(value) ? value.toFixed(1) : '—' }
function formatDate(value?: string) { return value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(value)) : '发布时间未提供' }
function rankClass(index: number) { return index === 0 ? 'rank-gold' : index === 1 ? 'rank-silver' : index === 2 ? 'rank-bronze' : '' }
function slugify(value: string) { return value.toLocaleLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 90) || `workflow-${Date.now().toString(36)}` }
function hydrateImportedIds() { try { importedIds.value = new Set(JSON.parse(localStorage.getItem('pcd-workflow-market-imports') || '[]')) } catch { importedIds.value = new Set() } }
function persistImportedIds() { localStorage.setItem('pcd-workflow-market-imports', JSON.stringify([...importedIds.value])) }
function hydrateRoute() { query.value = typeof route.query.q === 'string' ? route.query.q : ''; category.value = typeof route.query.category === 'string' ? route.query.category : ''; sortBy.value = ['published', 'imports', 'rating'].includes(String(route.query.sort)) ? route.query.sort as typeof sortBy.value : 'relevance'; page.value = Math.max(1, Number(route.query.page) || 1) }
function syncRoute() { page.value = Math.min(page.value, totalPages.value); void router.replace({ query: { ...(query.value ? { q: query.value } : {}), ...(category.value ? { category: category.value } : {}), ...(sortBy.value !== 'relevance' ? { sort: sortBy.value } : {}), ...(page.value > 1 ? { page: String(page.value) } : {}) } }) }
function setCategory(value: string) { category.value = value; page.value = 1; syncRoute() }
function submitSearch() { suggestionsOpen.value = false; page.value = 1; syncRoute(); void load() }
function clearSearch() { suggestionsOpen.value = false; query.value = ''; page.value = 1; syncRoute(); void load() }
function scheduleSearch() { if (searchTimer) clearTimeout(searchTimer); searchTimer = setTimeout(() => { page.value = 1; syncRoute(); void load() }, 300) }
function resetFilters() { query.value = ''; category.value = ''; sortBy.value = 'relevance'; page.value = 1; syncRoute(); void load() }
function selectSuggestion(item: WorkflowMarketplaceItem) { query.value = item.name; suggestionsOpen.value = false; page.value = 1; syncRoute(); void load() }
function goPage(value: number) { page.value = Math.min(Math.max(value, 1), totalPages.value); syncRoute(); window.scrollTo({ top: 0, behavior: 'smooth' }) }
function openDetail(item: WorkflowMarketplaceItem) { void router.push(`/app/workflow-market/${encodeURIComponent(item.workflowId)}`) }
function importTemplate(item: WorkflowMarketplaceItem) { pendingImport.value = item; importName.value = `${item.name} 副本`; importSlug.value = slugify(`imported-${item.slug}-${Date.now().toString(36)}`) }
async function confirmImport() {
  if (!pendingImport.value || !importName.value || !importSlug.value) return
  /* [REQ-WORKFLOW-MARKET-8.7~8.17] 导入只调用现有模板复制接口；本地已导入标记仅用于当前浏览器的交互反馈，不替代服务端归属校验。 */
  importingId.value = pendingImport.value.workflowId
  try { const result = await importWorkflowTemplateApi(pendingImport.value.workflowId, importName.value, importSlug.value); importedIds.value = new Set([...importedIds.value, pendingImport.value.workflowId]); persistImportedIds(); toast.showToast('模板已导入，可在 IDE 中继续配置', 'success'); pendingImport.value = null; await router.push(`/app/workflows/${encodeURIComponent(result.data.workflowId)}/edit`) }
  catch (cause: unknown) { toast.showToast(cause instanceof Error ? cause.message : '模板导入失败', 'error') }
  finally { importingId.value = '' }
}
async function load() { loading.value = true; error.value = ''; try { const response = await listWorkflowMarketplaceApi(query.value); items.value = response.data || []; page.value = Math.min(page.value, totalPages.value) } catch (cause: unknown) { items.value = []; error.value = cause instanceof Error ? cause.message : '模板市场请求失败，请稍后重试。' } finally { loading.value = false } }
watch(() => route.query, hydrateRoute, { immediate: true, deep: true }); watch([category, sortBy], () => { page.value = 1 }); watch(totalPages, value => { page.value = Math.min(page.value, value) })
onMounted(() => { hydrateImportedIds(); void load() }); onBeforeUnmount(() => { if (searchTimer) clearTimeout(searchTimer) })
</script>

<style scoped>
