utton:hover { border-color:#047857;background:#d1fae5;color:#047857; }.workflow-market-hero__aside { display:grid;gap:8px;align-content:center;border:1px solid #d0d7de;border-radius:10px;background:rgba(255,255,255,.75);padding:12px; }.workflow-market-hero__aside>div { display:grid;grid-template-columns:28px minmax(0,1fr);column-gap:9px;padding:7px; }.workflow-market-hero__aside i { grid-row:span 2;display:inline-flex;width:28px;height:28px;align-items:center;justify-content:center;border-radius:7px;background:#d1fae5;color:#047857; }.workflow-market-hero__aside b { color:#24292f;font-size:12px; }.workflow-market-hero__aside span { margin-top:2px;color:#57606a;font-size:10px; }.workflow-toolbar { display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #d0d7de; }.workflow-tabs { display:flex;overflow-x:auto; }.workflow-tabs button { display:inline-flex;align-items:center;gap:6px;border-bottom:2px solid transparent;padding:10px 10px;color:#57606a;font-size:12px;white-space:nowrap; }.workflow-tabs button:hover,.workflow-tabs button.active { border-bottom-color:#34d399;color:#24292f;font-weight:700; }.workflow-tabs small { border-radius:999px;background:#eaeef2;padding:1px 5px;color:#57606a;font-size:9px; }.workflow-toolbar>label { display:flex;align-items:center;gap:6px;color:#57606a;font-size:12px; }.workflow-toolbar select { border:1px solid #d0d7de;border-radius:6px;background:#fff;padding:6px;color:#24292f;font-size:12px; }.workflow-section { margin-top:28px; }.workflow-section__heading { display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px; }.workflow-section__heading h2 { margin:4px 0 0;color:#24292f;font-size:20px; }.workflow-section__heading p { margin:5px 0 0;color:#57606a;font-size:12px; }.workflow-section__heading>button { display:inline-flex;align-items:center;gap:6px;margin-top:6px;color:#047857;font-size:12px;white-space:nowrap; }.workflow-section__heading>span 